// Validar extracción — nodo Code de [003] Abonos a distancia (plan §1 nodo 9, reglas V-1…V-8 de plan §7.4).
// Modo «Run Once for All Items» (un correo por vuelta del bucle). Comprueba la salida de
// «Extraer datos del pago (IA)» comparándola con el texto original del correo.
// No consulta la API, no recalcula nada de la app y no decide el apartado.
// Salida: los seis campos aplanados + decision_extraccion (pago | no_pago | dudoso) + motivo.
// Una extracción dudosa NUNCA llega a registrar: «¿Es un pago?» la manda a «Preguntar a Marisa».

const correo = $('Preparar datos del correo').first().json;
const entrada = ($input.first() && $input.first().json) || {};
const CAMPOS = ['es_pago', 'tipo', 'ordenante', 'importe', 'concepto', 'referencia_apartado'];
const TIPOS = ['bizum', 'transferencia', 'desconocido'];

function salida(datos, decision, motivo) {
  const base = {};
  for (const c of CAMPOS) base[c] = datos && datos[c] !== undefined ? datos[c] : null;
  return [{ json: { ...base, decision_extraccion: decision, motivo }, pairedItem: { item: 0 } }];
}

// V-1: la IA falló (salida de error tras los reintentos) o no devolvió el objeto esperado.
let ex = entrada.output;
if (typeof ex === 'string') {
  try { ex = JSON.parse(ex); } catch (e) { ex = null; }
}
if (entrada.error || !ex || typeof ex !== 'object' || Array.isArray(ex)
    || !CAMPOS.every((c) => Object.prototype.hasOwnProperty.call(ex, c))) {
  return salida(ex && typeof ex === 'object' ? ex : {}, 'dudoso', 'La IA no devolvió datos válidos');
}

// V-2: es_pago booleano.
if (typeof ex.es_pago !== 'boolean') {
  return salida(ex, 'dudoso', 'La IA no indicó con claridad si el correo es un pago');
}

// V-3: «no es un pago» pero trae datos de pago → incoherente, no se ignora en silencio.
if (ex.es_pago === false) {
  if (ex.importe !== null || ex.ordenante !== null || ex.referencia_apartado !== null) {
    return salida(ex, 'dudoso', 'Extracción incoherente: la IA dice que no es un pago pero devuelve importe, ordenante o referencia');
  }
  return salida(ex, 'no_pago', null);
}

// V-4: tipo válido.
if (!TIPOS.includes(ex.tipo)) {
  return salida(ex, 'dudoso', 'Tipo de pago no válido en la extracción');
}

// V-5: importe número > 0 con como máximo 2 decimales.
const imp = ex.importe;
if (typeof imp !== 'number' || !Number.isFinite(imp) || imp <= 0
    || Math.abs(imp * 100 - Math.round(imp * 100)) > 1e-9) {
  return salida(ex, 'dudoso', 'Importe no válido');
}

// V-6: ordenante no vacío.
if (typeof ex.ordenante !== 'string' || ex.ordenante.trim() === '') {
  return salida(ex, 'dudoso', 'Sin ordenante');
}

// V-7: la referencia, si existe, son solo dígitos y aparece literalmente en el correo
// junto a «apartado», «ap.», «#», «nº», «n.º», «núm.», «número».
if (ex.referencia_apartado !== null) {
  const ref = String(ex.referencia_apartado).trim();
  if (!/^\d+$/.test(ref)) {
    return salida(ex, 'dudoso', 'Referencia de apartado no válida');
  }
  const texto = `${correo.asunto || ''}\n${correo.cuerpo || ''}`;
  const marca = '(?:(?:apartado|ap\\.)\\s*(?:#|n\\.?\\s?[º°]|n[uú]m(?:\\.|ero)?)?|#|n\\.?\\s?[º°]|n[uú]m(?:\\.|ero))';
  const patron = new RegExp(`(?<![\\p{L}\\d])${marca}\\s*0*${Number(ref)}(?!\\d)`, 'iu');
  if (!patron.test(texto)) {
    return salida(ex, 'dudoso', 'Referencia de apartado no presente en el correo (posible alucinación)');
  }
}

// V-8: es un pago pero no se sabe si es Bizum o transferencia.
if (ex.tipo === 'desconocido') {
  return salida(ex, 'dudoso', 'No se sabe si es Bizum o transferencia');
}

return salida(ex, 'pago', null);

// Buscar candidatos — nodo Code de [003] Abonos a distancia (plan §1, nodo 12).
// Modo: «Run Once for All Items». Casa la extracción de la IA (ordenante, concepto,
// referencia_apartado) con los apartados activos de la API y devuelve los candidatos.
// Solo identifica: no comprueba importe ni plazo (eso es «¿Se puede abonar?»), no
// recalcula importes y copia los datos del apartado tal cual llegan de la API.
// Sin HTTP ni secretos. La decisión (unico/dudoso/desconocido) la usa el Switch
// «¿Cuántos candidatos?».

// ---------- Normalización ----------
function normalizar(texto) {
  return String(texto == null ? '' : texto)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')      // quita tildes y diéresis
    .toUpperCase()
    .replace(/[^A-Z0-9Ñ ]+/g, ' ')          // puntuación → espacio (Ñ ya es N tras NFD)
    .replace(/\s+/g, ' ')
    .trim();
}

function palabras(texto) {
  const n = normalizar(texto);
  return n ? n.split(' ') : [];
}

// Raíz singular/plural: ZUECOS→ZUECO, MOCASINES→MOCASIN, DEPORTIVAS→DEPORTIVA.
function raices(p) {
  const r = new Set([p]);
  if (p.length > 3 && p.endsWith('S')) r.add(p.slice(0, -1));
  if (p.length > 4 && p.endsWith('ES')) r.add(p.slice(0, -2));
  return r;
}

function mismaRaiz(a, b) {
  const ra = raices(a);
  for (const x of raices(b)) if (ra.has(x)) return true;
  return false;
}

// Palabras vacías del concepto (no describen el producto).
const VACIAS = new Set([
  'ABONO', 'ABONOS', 'ABONAR', 'LIQUIDAR', 'LIQUIDACION', 'LIQUIDO', 'PAGO', 'PAGOS', 'PAGAR',
  'APARTADO', 'APARTADOS', 'AP', 'NUM', 'NUMERO', 'N', 'NO', 'RESTO', 'PLAZO', 'CUOTA', 'BIZUM',
  'TRANSFERENCIA', 'DE', 'DEL', 'LA', 'EL', 'LOS', 'LAS', 'LO', 'UN', 'UNA', 'UNOS', 'UNAS',
  'POR', 'PARA', 'CON', 'SIN', 'AL', 'Y', 'E', 'O', 'EN', 'A', 'MI', 'MIS', 'SU', 'SUS', 'TU',
  'QUE', 'ES', 'GRACIAS', 'PERDON', 'RETRASO', 'HOLA',
]);

function palabrasConcepto(concepto) {
  return palabras(concepto).filter((p) => p.length >= 3 && !/^\d+$/.test(p) && !VACIAS.has(p));
}

function conceptoCompatible(concepto, producto) {
  const c = palabrasConcepto(concepto);
  const prod = palabras(producto);
  return c.some((pc) => prod.some((pp) => mismaRaiz(pc, pp)));
}

// ---------- Nombres ----------
// completo: ≥2 palabras de ≥2 letras y ninguna inicial suelta.
// abreviado: alguna palabra de 1 letra («LAURA O.», «ROMERO D»).
// parcial: una sola palabra («CARMEN»): se trata como abreviado (necesita concepto).
function tipoNombre(ordenante) {
  const ps = palabras(ordenante).filter((p) => /^[A-Z]+$/.test(p));
  if (ps.length === 0) return { tipo: 'vacio', ps };
  if (ps.some((p) => p.length === 1)) return { tipo: 'abreviado', ps };
  if (ps.length >= 2) return { tipo: 'completo', ps };
  return { tipo: 'parcial', ps };
}

// Nombre completo: todas las palabras del cliente están en el ordenante,
// o el ordenante contiene nombre + primer apellido del cliente.
function casaNombreCompleto(psOrdenante, cliente) {
  const o = new Set(psOrdenante);
  const c = palabras(cliente);
  if (c.length === 0) return false;
  if (c.every((p) => o.has(p))) return true;
  return c.length >= 2 && o.has(c[0]) && o.has(c[1]);
}

// Nombre abreviado/parcial: cada palabra completa coincide con una palabra del cliente
// y cada inicial con la inicial de otra palabra distinta. Al menos una palabra completa.
function casaNombreAbreviado(psOrdenante, cliente) {
  const c = palabras(cliente);
  const usadas = new Set();
  const completas = psOrdenante.filter((p) => p.length >= 2);
  const iniciales = psOrdenante.filter((p) => p.length === 1);
  if (completas.length === 0) return false;
  for (const p of completas) {
    const i = c.findIndex((w, k) => !usadas.has(k) && w === p);
    if (i < 0) return false;
    usadas.add(i);
  }
  for (const ini of iniciales) {
    const i = c.findIndex((w, k) => !usadas.has(k) && w[0] === ini);
    if (i < 0) return false;
    usadas.add(i);
  }
  return true;
}

function nombreCompatible(nombre, cliente) {
  if (nombre.tipo === 'completo') return casaNombreCompleto(nombre.ps, cliente);
  if (nombre.tipo === 'abreviado' || nombre.tipo === 'parcial') return casaNombreAbreviado(nombre.ps, cliente);
  return false;
}

// «2», «#2», «nº 2», «apartado 2» → 2. Más de un número o ninguno → null.
function leerReferencia(ref) {
  if (ref === null || ref === undefined || ref === '') return null;
  const nums = String(ref).match(/\d+/g);
  if (!nums || nums.length !== 1) return NaN;
  return Number(nums[0]);
}

// Copia tal cual los campos que usa el flujo (sin modificar ni recalcular).
function copiaApartado(a) {
  return {
    id: a.id,
    cliente: a.cliente,
    producto: a.producto,
    pendiente: a.pendiente,
    fecha_limite: a.fecha_limite,
    estado: a.estado,
  };
}

function resultado(lista, decision, motivo, metodo) {
  return {
    candidatos: lista.map(copiaApartado),
    num_candidatos: lista.length,
    decision,
    motivo,
    metodo,
  };
}

// ---------- Función pura ----------
function buscarCandidatos(extraccion, apartados) {
  const ex = extraccion || {};
  const activos = (Array.isArray(apartados) ? apartados : []).filter(
    (a) => a && a.id !== undefined && a.id !== null && a.estado === 'activo'
  );
  const nombre = tipoNombre(ex.ordenante);
  const tieneConcepto = palabrasConcepto(ex.concepto).length > 0;
  const ordenanteTxt = ex.ordenante == null ? '(sin ordenante)' : String(ex.ordenante);

  // Regla 1: referencia explícita al apartado.
  const ref = leerReferencia(ex.referencia_apartado);
  if (ref !== null) {
    if (Number.isNaN(ref)) {
      return resultado([], 'dudoso', `Referencia de apartado no válida («${ex.referencia_apartado}»)`, 'referencia');
    }
    const ap = activos.filter((a) => Number(a.id) === ref);
    if (ap.length === 0) {
      return resultado([], 'dudoso', `El apartado ${ref} no existe o no está activo`, 'referencia');
    }
    if (nombre.tipo === 'vacio') {
      return resultado(ap, 'dudoso', `Referencia al apartado ${ref} sin ordenante con el que comprobarla`, 'referencia');
    }
    if (!nombreCompatible(nombre, ap[0].cliente)) {
      return resultado(ap, 'dudoso',
        `El ordenante «${ordenanteTxt}» no coincide con el cliente del apartado ${ref} («${ap[0].cliente}»)`, 'referencia');
    }
    return resultado(ap, 'unico', `Referencia al apartado ${ref} y el ordenante coincide con el cliente`, 'referencia');
  }

  if (nombre.tipo === 'vacio') {
    return resultado([], 'desconocido', 'Sin ordenante: no se puede identificar al cliente', 'nombre');
  }

  // Regla 2: nombre completo.
  if (nombre.tipo === 'completo') {
    const c = activos.filter((a) => casaNombreCompleto(nombre.ps, a.cliente));
    if (c.length === 1) return resultado(c, 'unico', `El ordenante «${ordenanteTxt}» coincide con un único apartado activo`, 'nombre');
    if (c.length === 0) return resultado(c, 'desconocido', `Cliente desconocido: ningún apartado activo a nombre de «${ordenanteTxt}»`, 'nombre');
    return resultado(c, 'dudoso', `Varios apartados activos (${c.length}) casan con «${ordenanteTxt}»`, 'nombre');
  }

  // Regla 3: nombre abreviado (o una sola palabra).
  const compatibles = activos.filter((a) => casaNombreAbreviado(nombre.ps, a.cliente));
  if (!tieneConcepto) {
    if (compatibles.length === 0) {
      return resultado([], 'desconocido', `Cliente desconocido: ningún apartado activo compatible con «${ordenanteTxt}»`, 'nombre');
    }
    return resultado(compatibles, 'dudoso',
      `Nombre abreviado («${ordenanteTxt}») sin concepto: ${compatibles.length} apartado(s) posible(s), hay que confirmar`, 'nombre');
  }
  if (compatibles.length === 0) {
    return resultado([], 'desconocido', `Cliente desconocido: ningún apartado activo compatible con «${ordenanteTxt}»`, 'concepto');
  }
  const porConcepto = compatibles.filter((a) => conceptoCompatible(ex.concepto, a.producto));
  if (porConcepto.length === 1) {
    return resultado(porConcepto, 'unico',
      `Nombre abreviado «${ordenanteTxt}» y concepto «${ex.concepto}» coinciden con un único apartado`, 'concepto');
  }
  if (porConcepto.length === 0) {
    return resultado(compatibles, 'dudoso',
      `Nombre abreviado «${ordenanteTxt}»: el concepto «${ex.concepto}» no coincide con el producto de ningún apartado posible`, 'concepto');
  }
  return resultado(porConcepto, 'dudoso',
    `Nombre abreviado «${ordenanteTxt}»: ${porConcepto.length} apartados casan con el concepto «${ex.concepto}»`, 'concepto');
}

// La salida del HTTP Request puede llegar como un item por apartado (lo normal en n8n),
// como un único item cuyo json es el array, o envuelta en {data: [...]}. Con
// «Always Output Data» y lista vacía llega un item {} → se descarta.
function leerApartados(items) {
  const out = [];
  for (const it of items || []) {
    const j = it && it.json !== undefined ? it.json : it;
    if (Array.isArray(j)) out.push(...j);
    else if (j && Array.isArray(j.data)) out.push(...j.data);
    else if (j && j.id !== undefined) out.push(j);
  }
  return out;
}

// La salida del Basic LLM Chain va en `output`; Validar extracción puede haberla aplanado.
function leerExtraccion(json) {
  const j = json || {};
  return j.output && typeof j.output === 'object' ? { ...j, ...j.output } : j;
}

// ---------- Envoltorio n8n ----------
// Se decide por $input (solo existe en n8n), no por `module`, que el sandbox puede definir.
if (typeof $input === 'undefined') {
  if (typeof module !== 'undefined') {
    module.exports = { buscarCandidatos, leerApartados, leerExtraccion, normalizar, mismaRaiz, tipoNombre };
  }
} else {
  const extraccion = leerExtraccion($('Validar extracción').first().json);
  const apartados = leerApartados($input.all());
  return [{ json: { ...extraccion, ...buscarCandidatos(extraccion, apartados) }, pairedItem: { item: 0 } }];
}
